		byte[] ownerKey = LmdbCompatibilityFixtures.idKey(ownerId);
		byte[] originalOwner = LmdbCompatibilityFixtures.nativeGet(directory, null, ownerKey);
		assertNotNull(originalOwner);

		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setLegacyReferenceCountRepairEnabled(true);
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.load();
		properties.setVersion("2");
