			byte[] actualNative = Files.readAllBytes(directory.resolve("values/data.mdb"));
			assertAll("an unsupported schema committed after preflight must remain untouched",
					() -> assertFalse(result.opened(), "the stale preflight cannot authorize startup"),
					() -> assertNotNull(result.failure(), "startup must report the unvalidated external writer"),
					() -> assertArrayEquals(UNSUPPORTED, finalMarker, "the external marker must survive"),
					() -> assertArrayEquals(expectedNative, actualNative, "no startup native write may commit"));
