	private static void runExternalWriter(Path directory, Path evidence) throws Exception {
		Path temporary = evidence.resolve("child-tmp");
		Files.createDirectories(temporary);
		Path log = evidence.resolve("external-writer.log");
		Process child = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"--enable-native-access=ALL-UNNAMED", "-ea", "-Djava.io.tmpdir=" + temporary,
				"-cp", System.getProperty("java.class.path"), ExternalWriter.class.getName(), directory.toString())
						.redirectErrorStream(true).redirectOutput(log.toFile()).start();
		if (!child.waitFor(30, TimeUnit.SECONDS)) {
			child.destroyForcibly();
			throw new IOException("independent native writer did not finish: " + log);
		}
		assertTrue(child.exitValue() == 0 && Files.readString(log).contains("UNSUPPORTED_MARKER_COMMITTED"),
				"independent writer must commit the unsupported marker: " + Files.readString(log));
	}

